hl.on("hyprland.start", function()
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP HYPRLAND_INSTANCE_SIGNATURE QT_QPA_PLATFORM")
    hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP HYPRLAND_INSTANCE_SIGNATURE QT_QPA_PLATFORM")
    hl.exec_cmd("hyprctl seterror disable")
    -- Floating-window clamp daemon (keeps floaters off the top bar / screen edges)
    hl.exec_cmd("~/.config/hypr/scripts/window_clamp.sh")
    -- "Drop and stay" daemon (re-floats windows where you dropped them after a drag)
    hl.exec_cmd("~/.config/hypr/scripts/floating_drag.sh")

    hl.exec_cmd("systemctl --user start hyprpolkitagent")
    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("quickshell -p ~/.config/hypr/scripts/quickshell/Shell.qml")
    hl.exec_cmd("~/.config/hypr/scripts/quickshell/focustime/launch_daemon.sh")
    hl.exec_cmd("~/.config/hypr/scripts/init.sh")
    hl.exec_cmd("~/.config/hypr/scripts/settings_watcher.sh &")
    hl.exec_cmd("playerctld")
    hl.exec_cmd([[swayosd-server --top-margin 0.9 --style "$HOME/.config/swayosd/style.css"]])
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    hl.exec_cmd("~/.config/hypr/scripts/volume_listener.sh")
    hl.exec_cmd("~/.config/hypr/scripts/update_notifier.sh")
    hl.exec_cmd([[bash -c 'amixer -c 2 sset "Mic Boost" 3 2>/dev/null; amixer -c 2 sset Capture cap 100% 2>/dev/null; wpctl set-volume @DEFAULT_AUDIO_SOURCE@ 1.30']])
    hl.exec_cmd("bash -c 'sleep 1 && ~/.config/hypr/scripts/qs_manager.sh toggle guide'")
end)
